  "steps": [
    {
      "id": 1,
      "claim": "The bystander's prior statement to a friend is an out‑of‑court statement that is inconsistent with his in‑court testimony.",
      "evidence": "Witness testified the light was red; on cross he said he previously told a friend he was not sure if it was yellow or red.",
      "weight": 0.25,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "A prior inconsistent statement is admissible as substantive evidence only if it was made under oath at a trial, hearing, or deposition (FRE 801(d)(1)(A)).",
      "evidence": "Federal Rules of Evidence 801(d)(1)(A).",
      "weight": 0.20,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "The bystander's prior statement was not made under oath; therefore it is hearsay and inadmissible for the truth of the matter asserted.",
      "evidence": "The statement was a casual remark to a friend, not a formal proceeding.",
      "weight": 0.20,
      "depends_on": [2]
    },
    {
      "id": 4,
      "claim": "Regardless of its hearsay status, a prior inconsistent statement may be used to impeach the witness’s credibility (FRE 613).",
      "evidence": "Federal Rules of Evidence 613 allows prior inconsistent statements for impeachment even if not under oath.",
      "weight": 0.20,
      "depends_on": [1]
    },
    {
      "id": 5,
      "claim": "When evidence is admissible for impeachment but not for substantive proof, the court must give a limiting instruction if a party requests it (FRE 105).",
      "evidence": "Federal Rules of Evidence 105.",
      "weight": 0.15,
      "depends_on": [3, 4]
    },
    {
      "id": 6,
      "claim": "The plaintiff, who called the witness, can request such a limiting instruction; the appropriate instruction is that the prior statement may be used only to impeach credibility, not as substantive evidence.",
      "evidence": "Rule‑based practice; the request may come from either party, but the plaintiff is the logical requester.",
      "weight": 0.10,
      "depends_on": [5]
    }
  ],
  "considered": [
    {
      "answer": "A",
      "reason_rejected": "Would allow the prior statement as substantive evidence, violating the hearsay rule because the statement was not made under oath."
    },
    {
      "answer": "B",
      "reason_rejected": "Extrinsic proof of the prior statement is generally not permitted for a lay witness’s prior inconsistent statement; the issue is the limiting instruction, not additional witnesses."
    },
    {
      "answer": "C",
      "reason_rejected": "Disregarding the bystander's testimony altogether is unnecessary; the testimony is admissible, only its credibility is in question."
    }
  ]
}
